export const getPredictionData = (locationId: string): PredictionData => {
  return riskProfiles[locationId] || generateDefaultPrediction(locationId);
};

function generateDefaultPrediction(locationId: string): PredictionData {
  const score = Math.floor(Math.random() * 40) + 20;
  const risk = score >= 75 ? 'critical' : score >= 60 ? 'high' : score >= 35 ? 'moderate' : 'low';

  return {
    locationId,
    timestamp: new Date().toISOString(),
    overallRisk: risk,
    riskScore: score,
    confidence: 80 + Math.random() * 15,
    factors: [
      { name: 'Terrain', value: score + 5, weight: 0.25, description: 'Local terrain characteristics', trend: 'stable' },
      { name: 'Rainfall', value: score - 5, weight: 0.2, description: 'Regional rainfall patterns', trend: 'stable' },
      { name: 'Soil', value: score, weight: 0.2, description: 'Soil conditions', trend: 'stable' },
    ],
    metrics: {
      rainfall: { current: 20 + Math.random() * 40, forecast24h: 30 + Math.random() * 50, forecast72h: 80 + Math.random() * 120, unit: 'mm' },
      soilMoisture: { current: 40 + Math.random() * 40, depth: '0-3m', unit: '%' },
      temperature: { current: 22 + Math.random() * 10, min: 16 + Math.random() * 5, max: 28 + Math.random() * 8, unit: '°C' },
      humidity: { current: 70 + Math.random() * 25, unit: '%' },
      slope: { angle: 15 + Math.random() * 30, aspect: 'Variable' },
      vegetation: { ndvi: 0.3 + Math.random() * 0.4, coverage: 'Variable' },
      groundwater: { level: 3 + Math.random() * 10, unit: 'm below surface', trend: 'stable' },
    },
    historicalData: [],
    forecast: [
      { day: 'Today', rainfall: 20, riskScore: score, temperature: 25 },
      { day: 'Tomorrow', rainfall: 35, riskScore: score + 5, temperature: 24 },
      { day: 'Day 3', rainfall: 25, riskScore: score - 3, temperature: 25 },
      { day: 'Day 4', rainfall: 15, riskScore: score - 10, temperature: 26 },
      { day: 'Day 5', rainfall: 8, riskScore: score - 18, temperature: 27 },
      { day: 'Day 6', rainfall: 3, riskScore: score - 25, temperature: 28 },
      { day: 'Day 7', rainfall: 1, riskScore: score - 30, temperature: 29 },
    ],
    recommendations: [
      { id: 'r1', priority: 'medium', category: 'Monitoring', title: 'Continue Monitoring', description: 'Maintain current monitoring levels.', timeframe: 'Ongoing' },
    ],
    riskZones: [],
  };
}
